// ============================================================================
// Note-format sample-preview cache (Redis, content-addressed).
// ----------------------------------------------------------------------------
// The live sample-note preview is generated by a real model call, so it's
// cached so it runs ONCE per distinct template content (the spec's "once per
// template version"), not on every review-screen load. The review screen
// operates on an UNSAVED draft (no row id / version yet), so the cache key is a
// content-hash of the draft's prompt-relevant fields + the synthetic-transcript
// version — NOT a NoteTemplate row (which doesn't exist pre-save). This also
// means an identical template, before AND after save/activate, hits the same
// cache entry for free.
//
// Redis (not a DB column): no migration, regenerable, auto-evicting (TTL). The
// cached value is a derived, non-PHI sample (synthetic transcript only), so a
// cache miss/eviction is harmless — it just regenerates.
// ============================================================================

import { createHash } from 'node:crypto';

import { getSharedRedisConnection } from '@/lib/queue';
import type { ParsedTemplateDraft } from '@/lib/note-template-parse/note-template-schema';

const KEY_PREFIX = 'notefmt:preview:v1:';
/** 7 days. The preview is cheap to regenerate; this just bounds re-spend on a
 *  template a doctor revisits within the week. */
const TTL_SECONDS = 7 * 24 * 60 * 60;

/** Content-hash of the prompt-relevant draft fields + the synthetic-transcript
 *  version. Stable across review reloads for identical content; changes the
 *  moment the doctor edits a section/style (→ a fresh generation). */
export function previewCacheKey(
  draft: ParsedTemplateDraft,
  transcriptVersion: string
): string {
  // Canonicalize only the fields that change the generated note. `name` is
  // included because it can surface in the rendered note's title/heading.
  const canonical = JSON.stringify({
    name: draft.name,
    encounterType: draft.encounterType,
    sections: draft.sections,
    styleProfile: draft.styleProfile,
    transcriptVersion,
  });
  const hash = createHash('sha256').update(canonical, 'utf8').digest('hex');
  return `${KEY_PREFIX}${hash}`;
}

/** Returns the cached sample markdown, or null on miss / any Redis error
 *  (fail-soft: a cache problem must never block the preview — it regenerates). */
export async function getCachedPreview(key: string): Promise<string | null> {
  try {
    return await getSharedRedisConnection().get(key);
  } catch {
    return null;
  }
}

/** Cache the generated sample. Fail-soft: a write error is swallowed (the
 *  preview still rendered; the next load just regenerates). */
export async function setCachedPreview(key: string, markdown: string): Promise<void> {
  try {
    await getSharedRedisConnection().set(key, markdown, 'EX', TTL_SECONDS);
  } catch {
    // best-effort cache; ignore
  }
}
